802	/**
803	 * Refund a per-server disk expansion that was paid for but never delivered.
804	 *
805	 * The DISK_EXPAND handler advances `Server.extraDiskGB` only AFTER the disk has
806	 * really grown, so that field is the ground truth for "did the customer get what
807	 * they paid for". We refund only when it never reached the job's target — which
808	 * also keeps this safe against the partial-success case (disk grown, filesystem
809	 * left for the customer to grow by hand): that path completes successfully, sets
810	 * extraDiskGB, and is therefore never refunded.
811	 *
812	 * Idempotent per job via the reconcile audit marker.
813	 */
814	async function reconcileFailedDiskExpand(job: Job) {
815	  const p = (job.payload ?? {}) as { prorateCents?: number; addGB?: number; targetExtraDiskGB?: number };
816	  const cents = p.prorateCents ?? 0;
817	  if (cents <= 0 || !job.serverId) return;
818	
819	  const already = await db.auditLog.findFirst({
820	    where: { action: "server.disk_expand.reconcile", detail: { contains: `job=${job.id}` } },
821	  });
822	  if (already) return;
823	
824	  const server = await db.server.findUnique({
825	    where: { id: job.serverId },
826	    select: { userId: true, hostname: true, extraDiskGB: true },
827	  });
828	  if (!server) return;
829	
830	  // The expansion actually landed (or a later one superseded it) — the customer
831	  // has the storage, so the charge stands. Nothing to unwind.
832	  const target = Number(p.targetExtraDiskGB ?? 0);
833	  if (target > 0 && server.extraDiskGB >= target) return;
834	
835	  try {
836	    await db.$transaction([
837	      db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
838	      db.walletTransaction.create({
839	        data: {
840	          userId: server.userId,
841	          amountCents: cents,
842	          description: `Refund: failed storage expansion (+${p.addGB ?? "?"} GB) — ${server.hostname}`,
843	        },
844	      }),
845	      db.notification.create({
846	        data: {
847	          userId: server.userId,
848	          title: `Storage expansion failed on ${server.hostname} — refunded`,
849	          body: `We couldn't add the storage, so $${(cents / 100).toFixed(2)} has been credited back to your wallet. Your server and its data are untouched.`,

880	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
881	 * double-reverse.
882	 */
883	async function reconcileFailedJob(job: Job) {
884	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
885	  if (job.type !== "RESIZE") return;
886	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
887	  const cents = p.prorateCents ?? 0;
888	  if (cents <= 0 || !job.serverId) return;
889	
890	  // Idempotency: skip if we already reversed this exact job.
891	  const already = await db.auditLog.findFirst({
892	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
893	  });
894	  if (already) return;
895	
896	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
897	  if (!server) return;
898	
899	  try {
900	    if (p.direction === "up") {
901	      // Upgrade charge never delivered → refund the prorated charge.
902	      await db.$transaction([
903	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
904	        db.walletTransaction.create({
905	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
906	        }),
907	      ]);
908	    } else if (p.direction === "down") {
909	      // Downgrade credit was given but hardware unchanged → claw the credit back.
910	      // Guarded so it can never drive the balance negative; if the customer already
911	      // spent it, we log and leave it (best-effort — they keep a small windfall).
912	      await db.$transaction(async (tx) => {
913	        await debitWallet(tx, server.userId, cents);
914	        await tx.walletTransaction.create({
915	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
916	        });
917	      });
918	    }
919	    await db.auditLog.create({
920	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
921	    });
922	  } catch (e: any) {
923	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
924	    await db.auditLog.create({
925	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
926	    }).catch(() => {});
927	  }
928	}
