export type MigrationStepResult = {
  step: string;
  // running  = verified running on the target
  // copied   = placed on the target but NOT verified running (may need a manual step)
  // failed   = attempted, failed (reason in detail) — did NOT fail the migration
  // skipped  = nothing to do
  status: "running" | "copied" | "failed" | "skipped";
  detail: string;
};

/**
 * A named thing that is NOT finished, with why and the exact command that
 * finishes it. Shared shape for TLS gaps and for the blocking problems the
 * systemd pre-flight / health gate find, so the summary reads the same way
 * whatever produced the entry.
 */
export type PendingItem = { domain: string; why: string; fix: string };

/**
 * The terminal outcome of a real run, as judged by this engine.
 *
 *   COMPLETED             — every domain the SOURCE served is serving here, and
 *                           every migrated unit is healthy.
 *   COMPLETED_WITH_ISSUES — the move finished but at least one source domain is
 *                           dark, or a migrated service is crash-looping. The
 *                           customer MUST see this as "not done yet".
 *
 * Introduced after a real run on 2026-07-25 logged `Sites actually serving: 4/4`
 * while six of the customer's domains were dark and `nexis-next.service` had
 * crash-looped 78 times. A run that cannot fail is not a check.
 */
export type MigrationOutcome = "COMPLETED" | "COMPLETED_WITH_ISSUES";

export type RealMigrationSummary = {
  results: MigrationStepResult[];
  verifiedRunning: string[];
  needsAttention: string[];
  /** Hostnames confirmed to have a live certificate on the new server. */
  tlsSecured?: string[];
  /** Hostnames still without TLS, each with why and the exact command to fix it. */
  tlsPending?: TlsPending[];
  /**
   * Hostnames HTTP-probed at the end, with the status code each returned.
   * `reason` is the honest explanation whenever `serving` is false — including
   * "answered, but with the stock Apache/nginx default page" and "the
   * certificate served here does not cover this name".
   */
  siteProbes?: { domain: string; http: string; https: string; serving: boolean; reason?: string }[];
  /**
   * THE DENOMINATOR. Every hostname the SOURCE server was configured to answer
   * on, taken from its own live vhost config — NOT the set we chose to publish.
   * Scoring against the generated-config set is what let the old summary report
   * 4/4 while six domains were dark.
   */
  sourceDomains?: string[];
  /** Source domains this server does not serve. Non-empty ⇒ COMPLETED_WITH_ISSUES. */
  unservedDomains?: string[];
  /** Blocking problems found by the systemd pre-flight / health gate. */
  blockers?: PendingItem[];
  /** COMPLETED or COMPLETED_WITH_ISSUES — see MigrationOutcome. */
  outcome?: MigrationOutcome;
  /** Plain-language reasons the outcome is COMPLETED_WITH_ISSUES (empty when clean). */
  outcomeReasons?: string[];
};

export type RealMigrationInput = {
  migration: MigrationRow;
  target: TargetServer | null;
  items: Items;
  report: ReportFn;
  /**
   * Optional TLS inputs, all resolved on the NXEON side (never read off the
   * customer's box). Omitting them simply drops the engine to a lower rung of
   * the certificate ladder, so existing callers keep working unchanged.
   */
  cloudflareToken?: string | null; // DNS-edit scoped token, for wildcard DNS-01
  acmeEmail?: string | null; // Let's Encrypt account contact
  knownDomains?: string[]; // the customer's registered Domain rows
  /**
   * Explicit consent to relocate Docker's stores onto an attached block-storage
   * volume. **Defaults to false** — the engine never takes a volume on its own,
   * because volumes are portable and mounting a system path on one makes the
   * volume undetachable. Falls back to `items.useVolumeForDocker` so the choice
   * can ride through Migration.items without a schema change.
   */
  useVolumeForDocker?: boolean;
};

