  }
  let volid: string | null = null;
  // 1) Preferred: the volid Proxmox kept/created at the slot we just wrote.
  const atSlot = volidOf(after[slot]);
  if (isRealVolid(atSlot)) {
    volid = atSlot;
  } else if (volume.diskName && isRealVolid(volume.diskName)) {
    // 2) Re-attach path: the disk we asked to attach is a known-good volid.
    volid = volume.diskName;
  } else {
    // 3) First-attach path where the slot read-back didn't yield a volid (pending
    //    config view, momentary omission, …): identify the disk that newly appeared.
    const appeared = diskVolids(after).filter((v) => !before.has(v));
    if (appeared.length === 1) volid = appeared[0];
  }

  await db.volume.update({
    where: { id: volume.id },
    // Never regress a previously-recorded good volid to null on a retry.
    data: { status: "ATTACHED", serverId: server.id, diskName: volid ?? volume.diskName ?? null },
  });
  await notify(
    volume.userId,
    `Volume "${volume.name}" attached to ${server.hostname}`,
    `${volume.sizeGB} GB is now available as ${slot}. Format and mount it inside the server to use it.`,
    `/dashboard/servers/${server.id}`
  );
}

/**
 * VOLUME_DETACH — detach the disk from the VM (Proxmox moves it to an "unused"
 * entry, preserving the data). The volume stays pinned to this server so it can
 * be re-attached here later.
 */
export async function volumeDetach(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  const server = volume.server;

  if (SANDBOX) {
    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
    if (server) {
      await notify(
        volume.userId,
        `Volume "${volume.name}" detached from ${server.hostname}`,
        "The volume and its data are preserved and can be re-attached (sandbox).",
        "/dashboard/volumes"
      );
    }
    return;
  }

  if (server?.vmid && volume.diskName) {
    const { conn } = await nodeFor(server);
    const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
    const key = keyForVolid(config, volume.diskName);
    if (key && key.startsWith("scsi")) {
      await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
    }
  }

  await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
  if (server) {
    await notify(
      volume.userId,
      `Volume "${volume.name}" detached from ${server.hostname}`,
      "The volume and its data are preserved and can be re-attached to the same server.",
      "/dashboard/volumes"
    );
  }
}

/**
 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
 * disk, and remove the Volume row.
 */
export async function volumeDelete(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  const server = volume.server;

  if (SANDBOX) {
    await db.volume.delete({ where: { id: volume.id } });
    await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
    return;
  }

  if (server?.vmid && volume.diskName) {
    const { conn } = await nodeFor(server);
    try {
      let config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
      let key = keyForVolid(config, volume.diskName);

      // If still mounted, detach to an "unused" entry first.
      if (key && key.startsWith("scsi")) {
        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
        config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
        key = keyForVolid(config, volume.diskName);
      }
      // Deleting an "unused" entry destroys the underlying disk.
      if (key) {
        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
      }
    } catch (e: any) {
      const msg = String(e?.body ?? e?.message ?? e);
      if (!msg.includes("does not exist")) throw e;
    }
  }

  await db.volume.delete({ where: { id: volume.id } });
  await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";

/**
 * Scheduled-backup sweep.
 *
 * `scheduledBackupSweep` finds RUNNING servers that opted into recurring backups
 * (`autoBackup=true`) whose last automatic backup is older than their configured
 * cadence (or which have never had one), and enqueues a BACKUP_CREATE job for
 * each — de-duping on any in-flight job so it's safe to call on a timer.
 *
 * NOTE: `worker/index.ts` owns the job loop; it already knows how to run
 * BACKUP_CREATE jobs. Wire this sweep into the main loop on a timer, e.g.:
 *
 *   import { scheduledBackupSweep } from "./backup-schedule";
 *   if (Date.now() - lastBackupSweep > 15 * 60_000) {
 *     lastBackupSweep = Date.now();
 *     try { await scheduledBackupSweep(); } catch (e) { console.error(e); }
 *   }
 */
export async function scheduledBackupSweep(): Promise<void> {
  if (SANDBOX) return; // no real backups run in the sandbox
  const now = Date.now();

  const candidates = await db.server.findMany({
    where: {
      status: "RUNNING",
      autoBackup: true,
      backupIntervalHours: { not: null },
    },
    select: {
      id: true,
      hostname: true,
      backupIntervalHours: true,
      lastAutoBackup: true,
    },
  });
  if (candidates.length === 0) return;

  let enqueued = 0;
  for (const s of candidates) {
    const intervalMs = (s.backupIntervalHours ?? 0) * 60 * 60_000;
    if (intervalMs <= 0) continue;

    // Due if it has never run, or the cadence has elapsed since the last one.
    const dueAt = s.lastAutoBackup ? s.lastAutoBackup.getTime() + intervalMs : 0;
    if (now < dueAt) continue;

    // Respect the one-in-flight-job-per-server invariant.
    const inflight = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (inflight > 0) continue;

    await db.job.create({ data: { type: "BACKUP_CREATE", serverId: s.id } });
    // Mark the schedule as satisfied now so a slow backup / a second sweep pass
    // doesn't pile up duplicate jobs; the timestamp anchors the next window.
    await db.server.update({
      where: { id: s.id },
      data: { lastAutoBackup: new Date() },
    });
    enqueued++;
  }

  if (enqueued > 0) console.log(`[backup-schedule] sweep enqueued ${enqueued} backup job(s)`);
}
