export async function backupRestore(job: Job): Promise<void> {
  const server = await loadServer(job.serverId!);
  if (SANDBOX) {
    // Simulate a successful restore — animate the bar 0→100 so staging shows it.
    const steps = [
      { pct: 8, step: "Stopping server" },
      { pct: 30, step: "Restoring archive… 25%" },
      { pct: 55, step: "Restoring archive… 55%" },
      { pct: 80, step: "Restoring archive… 85%" },
      { pct: 95, step: "Starting server" },
      { pct: 100, step: "Restore complete" },
    ];
    for (const s of steps) {
      await reportJobProgress(job.id, s.pct, s.step);
      await new Promise((r) => setTimeout(r, 500));
    }
    await notify(
      server.userId,
      `Backup restored on ${server.hostname}`,
      "Your server was restored from the selected backup (sandbox).",
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  if (!server.vmid) throw new Error("restore: server has no VM");

  const payload = (job.payload ?? {}) as { volid?: string };
  const volid = payload.volid;
  if (!volid) throw new Error("restore: missing volid");

  const conn = await nodeFor(server);
  const vmid = server.vmid;
  const wasRunning = server.status === "RUNNING";

  // 1) Stop the VM so the disk can be overwritten (ignore "already stopped").
  await reportJobProgress(job.id, 3, "Stopping server");
  try {
    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
    await conn.waitForTask(stopUpid);
  } catch {
    /* already stopped / not running */
  }
  await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });

  // 2) Restore the archive over the existing VMID (force overwrite). Storage is
  //    left to the archive's recorded config so disks land where they were.
  //    Task progress (0..100) is mapped into the 10..90 window of the bar.
  await reportJobProgress(job.id, 10, "Restoring archive…");
  const restoreUpid = await conn.post(`/nodes/${conn.node}/qemu`, {
    vmid,
    archive: volid,
    force: 1,
  });
  await waitForTaskProgress(
    conn,
    restoreUpid,
    (progress, step) => reportJobProgress(job.id, progress, step),
    { timeoutMs: 3_600_000, phase: "restore", base: 10, span: 80 }
  );

  // 3) Bring the VM back up if it was running before the restore.
  if (wasRunning) {
    await reportJobProgress(job.id, 95, "Starting server");
    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
    await conn.waitForTask(startUpid);
    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
  }
  await reportJobProgress(job.id, 100, "Restore complete");

  await notify(
    server.userId,
    `Backup restored on ${server.hostname}`,
    "Your server was restored from the selected backup. Any changes made after that backup are gone.",
    `/dashboard/servers/${server.id}`
  );
}

export async function resizeServerDown(
  serverId: string,
  newPlanId: string
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
  if (!newPlan?.active) return { error: "Plan not available." };
  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };

  // This action is downgrades only — upgrades go through resizeServer().
  if (newPlan.priceCents >= server.plan.priceCents) {
    return { error: "This is not a smaller plan — use the upgrade flow instead." };
  }
  // Disk can't shrink destructively; block the move rather than lose data.
  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
  // both the old and the new plan and is preserved verbatim across the resize, so
  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
  // does not shrink". Nothing here ever writes extraDiskGB.
  if (newPlan.diskGB < server.plan.diskGB) {
    return {
      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
    };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  // Prorated credit over the ACTUAL remaining duration, not a fraction of a single
  // term. `renewNow` can stack expiresAt many terms into the future, so the old
  // "fraction of one term" clamp under-credited (or over-credited) prepaid users.
  // Credit the monthly price difference for every remaining month. Null expiresAt
  // (free/admin servers) => 0.
  let creditCents = 0;
  if (!server.isFree && server.expiresAt) {
    const now = Date.now();
    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
    const monthlyDelta = server.plan.priceCents - newPlan.priceCents; // positive: old monthly > new monthly
    creditCents = Math.max(0, Math.round(monthlyDelta * remainingMonths));
  }

  await db.$transaction([
    ...(creditCents > 0
      ? [
          db.user.update({
            where: { id: server.userId },
            data: { balanceCents: { increment: creditCents } },
          }),
          db.walletTransaction.create({
            data: {
              userId: server.userId,
              amountCents: creditCents,
              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
            },
          }),
        ]
      : []),
    // Record the amount credited on the job so the worker's RESIZE handler can
    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
    // terminally fails — the credit is committed here, before the job runs.
    // INTEGRATION NEEDED: worker must honour payload.prorateCents/direction.
    db.job.create({
      data: {
        type: "RESIZE",
        serverId,
        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
      },
    }),
    db.auditLog.create({
      data: {
        userId: user.id,
        action: "server.resize_down",
        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
      },
    }),
  ]);

  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}
